def solve(grid, start, goal):
    def get_neighbours(position):
        row, col = position
        neighbours = [(row, col + 1), (row, col - 1), (row + 1, col), (row - 1, col)]
        return [(r, c) for r, c in neighbours if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.']

    def is_valid_path_path(path):
        return start in path and path[-1] == goal and len(path) == len(set(path)) and all(grid[r][c] == '.' for r, c in path)

    def backtrack(position, path):
        if position == goal or is_valid_path_path(path):
            return path
        if position in path: 
            return None
        path.append(position)
        for neighbour in get_neighbours(position):
            result = backtrack(neighbour, path.copy())  
            if result is not None:
                return result
        path.pop() 
        return None

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    return backtrack(start, [])

