def solve(grid, start, goal):
    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def is_free(x, y):
        return is_valid(x, y) and grid[x][y] == '.'

    def neighbors(x, y):
        return [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]

    def bids_path(start, goal):
        queue = [(start, [start])]
        while queue:
            (x, y), path = queue.pop(0)
            if (x, y) == goal:
                return path
            for nx, ny in neighbors(x, y):
                if is_valid(nx, ny) and (nx, ny) not in path:
                    new_path = path + [(nx, ny)]
                    if is_valid(nx, ny):
                        queue.append(((nx, ny), new_path))
            queue.reverse()

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if not bids_path(start, goal) or not bids_path(goal, start):
        return []

    graph = {}
    for x in range(len(grid)):
        for y in range(len(grid[0])):
            graph[(x, y)] = neighbors(x, y)

    def a_star(start, goal):
        queue = [(start, [start]) if not bids_path(start, goal) else bids_path(start, goal)[0:start+1], [], 0)]
        while queue:
            (pos, path, dist), came_from = heappop(queue)
            if pos == goal:
                path = [goal] + came_from[pos]
                assert all(grid[x][y] == '.' for x, y in path)
                return path
            for neighbor in graph[pos]:
                if is_valid(neighbor[0], neighbor[1]):
                    tentative_dist = dist + 1
                    new_pos = neighbor
                    if new_pos not in came_from:
                        priority = tentative_dist + abs(new_pos[0] - goal[0]) + abs(new_pos[1] - goal[1])
                        heappush(queue, ((new_pos, path + [new_pos], tentative_dist), came_from, priority))
        return []

    return a_star(start, goal)

