            ni, nj = r + j, c + k
            if (0 <= ni < len(grid)) and (0 <= nj < len(grid[0])) and grid[ni][nj] != '#':
                yield (ni, nj), i

    def matrix_dim(grid): return len(grid), len(grid[0])

    # Since grid only contains . and # and we know the # won't move we can encode valid positions and moves into weights where you can't move as infinity
    rows, cols = matrix_dim(grid)
    dist = [[float('inf')]*cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    weights = [[0 if (a, b) else float('inf') for (b, c) in enumerate(row)] for (a, row) in enumerate(grid)]
    moves = [[list(neighbours(a, b)) for b in range(cols)] for a in range(rows)]
    live = dist.copy()

    while any(any(w != float('inf') for w in row) for row in live):
        row_sum = any(sum(row) for row in live)
        if not row_sum:
            break #if row_sum is false (no row has a live weights) then there is no solution
        r = max(r for r in range(rows) if any(live[r]))
        for (n, move) in moves[r]: 
            if (w:= weights[n]): #is there a live weight here?
                expires = (dx, dy) = (r - n[0], n[1] - move)
                ld = dist[n[0]][n[1]] = min('.' not in (n:= grid[n[0]][n[1]]) and float('inf'), (0 if expires == (0, 0) else dist[r][move]-w) + base)
                live[n] = ld < dist[n[0]][n[1]] # Did the weight expire?
                dist[n[0]][n[1]] = min(dist[n[0]][n[1]], ld) # dist is always valid if a weight can be expired

    def backtrack_back(): 
        """Backtrack once off stack and propagate moves to stack upwards to reach start"""
        stack = [[goal]] #containing pointer to valid path and indices
        visited = set(goal)
        while stack: 
            path, (i, j) = stack.pop()
