from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([start])
    visited = set()
    while queue:
        x, y = queue.popleft()
        if (x, y) == goal:
            return [(x, y)] + backtrack(x, y)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.'
                and (nx, ny) not in visited):
                queue.append((nx, ny))
                visited.add((nx, ny))
    return []

def backtrack(x, y):
    path = [(x, y)]
    dx, dy = 0, 0
    for _ in range(10):  # up to 10 steps to unwind the path
        x, y = x - dx, y - dy
        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.':
            path.insert(0, (x, y))
        else:
            break
        for dx_, dy_ in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx_, y + dy_
            if (0 <= nx < len(grid) and 0 <= ny < len(grid[0])
                and grid[nx][ny] == '.' and (nx, ny) != (x, y)):
                x, y = nx, ny
                dx, dy = dx_, dy_
                break
    return path

