def solve(grid, start, goal):
    """
    Finds a path between two cells of a grid.

    Args:
        grid (list of str): A grid where . is a free cell and # is a wall.
        start (tuple): 0-based indices of the start cell.
        goal (tuple): 0-based indices of the goal cell.

    Returns:
        list of tuple: A list of (row, col) tuples representing a path from start to goal.
    """

    def valid(x, y):
        """Checks if a cell is within the grid and free."""
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def neighbours(x, y):
        """Returns the 4 orthogonal neighbours of a cell."""
        return [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]

    def distance(cell1, cell2):
        """Calculates the Manhattan distance between two cells."""
        return abs(cell1[0] - cell2[0]) + abs(cell1[1] - cell2[1])

    def heuristic(cell):
        """Calculates the Manhattan distance from a cell to the goal."""
        return distance(cell, goal)

    def astar(start):
        """Finds the shortest path using A* search."""
        queue = [(0, start)]  # priority is the heuristic value + distance traveled
        cost = {start: 0}  # distance traveled to reach each cell
        came_from = {}  # backtrace to find the path

        while queue:
            _, current = min(queue)
            if current == goal:
                return reconstruct_path(came_from, current)

            queue.remove((cost[current], current))

            for neighbour in neighbours(*current):
                if valid(*neighbour) and neighbour not in cost:
                    cost[neighbour] = cost[current] + 1
                    priority = heuristic(neighbour) + cost[neighbour]
                    queue.append((priority, neighbour))
                    came_from[neighbour] = current

        return []

    def reconstruct_path(came_from, current):
        """Reconstructs the path from the start to the goal."""
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    for cell in [(start[0], start[1])]:
        if grid[cell[0]][cell[1]] == '#':
            return []

    return astar(start)

