def solve(grid, start, goal):
    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def neighbours(cell):
        row, col = cell
        return [((row-1, col), 'up'),
                ((row+1, col), 'down'),
                ((row, col-1), 'left'),
                ((row, col+1), 'right')]

    def dfs(cell, path):
        if cell == goal:
            return [path + [cell]]
        for neighbour, _ in neighbours(cell):
            if is_valid(neighbour[0], neighbour[1]) and neighbour not in path:
                result = dfs(neighbour, path + [cell])
                if result:
                    return result
        return None

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#':
        return []
    return dfs(start, []) if is_valid(start[0], start[1]) else []

