def solve(grid, start, goal):
    def neighbours((row, col)):
        yield (row - 1, col)
        yield (row + 1, col)
        yield (row, col - 1)
        yield (row, col + 1)

    if grid[row][col] == '#':
        return []

    if (row, col) == start == goal:
        return [start]

    history = set()

    def backtrack(current):
        if current == goal:
            return [current]
        history.add(current)
        for neighbour in neighbours(current):
            if (0 <= neighbour[0] < len(grid) and
                    0 <= neighbour[1] < len(grid[0]) and
                    grid[neighbour[0]][neighbour[1]] == '.' and
                    neighbour not in history):
                result = backtrack(neighbour)
                if result:
                    return [current] + result
        return []

    return backtrack(start)

