def solve(grid, start, goal):
    def get_neighbours(pos):
        row, col = pos
        return [
            (row - 1, col) if row > 0 and grid[row - 1][col] != '#' else None,
            (row + 1, col) if row < len(grid) - 1 and grid[row + 1][col] != '#' else None,
            (row, col - 1) if col > 0 and grid[row][col - 1] != '#' else None,
            (row, col + 1) if col < len(grid[0]) - 1 and grid[row][col + 1] != '#' else None,
        ]

    from collections import deque
    queue = deque([[start]])
    while queue:
        path = queue.popleft()
        pos = path[-1]
        if pos == goal:
            return path
        for neighbour in get_neighbours(pos):
            if neighbour and neighbour not in path:
                queue.append(path + [neighbour])
    return []
