    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def solve(grid, start, goal):
    visited = set([start])
    queue = deque([start])
    paths = {}
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def append_path(current, path):
        new_path = list(path)
        new_path.append(current)
        return tuple(new_path)

    while queue:
        current = queue.popleft()
        path = paths.get(current, [current])
        for dr, dc in directions:
            new_row = current[0] + dr
            new_col = current[1] + dc
            if is_valid(grid, new_row, new_col) and (new_row, new_col) not in visited:
                if (new_row, new_col) == goal:
                    return list(path) + [(new_row, new_col)]
                visited.add((new_row, new_col))
                queue.append((new_row, new_col))
                paths[(new_row, new_col)] = append_path((new_row, new_col), path)
    return []

