            if is_valid(grid, nr, nc) and (nr, nc) not in visited:
                if (nr, nc) == goal:
                    return path + [(nr, nc)]
                visited.add((nr, nc))
                queue.append(((nr, nc), path + [(nr, nc)]))

    return []

