def find_all_paths(grid, start, goal, path=[]):
    """Find all paths in the grid from the start cell to the goal cell."""
    row, col = start
    path = path + [start]
    if start == goal:
        return [path]
    if grid[row][col] == '#':
        return []
    grid[row] = grid[row][:col] + '.' + grid[row][col+1:]
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    all_paths = []
    for dr, dc in directions:
        r, c = row + dr, col + dc
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            all_paths.extend(find_all_paths(grid, (r, c), goal, path))
    grid[row] = grid[row][:col] + '#' + grid[row][col+1:]
    return all_paths

def solve(grid, start, goal):
    """Find a path between two cells of a grid."""
    return find_all_paths(grid, start, goal)

