def solve(grid, start, goal):
    def inBounds(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0])

    def isFree(row, col):
        return inBounds(row, col) and grid[row][col] == '.'

    def isValidMove(row, col, path):
        return zip([row], [col]) not in path[:-1] and isFree(row, col)

    def dfs(row, col, path):
        if (row, col) == goal:
            return path + [(row, col)]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if isValidMove(r, c, path):
                result = dfs(r, c, path + [(row, col)])
                if result:
                    return result
        return None

    if start == goal and isFree(*start):
        return [start]
    if not isFree(*start) or not isFree(*goal):
        return []
    return dfs(*start, []) or []

