    queue = deque([start])
    visited = set([start])

    while queue:
        row, col = queue.popleft()
        if (row, col) == goal:
            path = []
            while (row, col) != start:
                path.append((row, col))
                row -= directions[-1][0]
                col -= directions[-1][1]
            path.append(start)
            return list(reversed(path))

        for dr, dc in directions:
            r, c = row + dr, col + dc
            if is_valid(r, c) and (r, c) not in visited:
                queue.append((r, c))
                visited.add((r, c))

    return []
