    def valid(p):
        r, c = p
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def neighbors(p):
        r, c = p
        return [
            (r-1, c), (r+1, c), (r, c-1), (r, c+1)
        ]

    if start == goal or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return [start] if (start == goal and grid[start[0]][start[1]] == '.') else []

    stack = [start]
    seen = set([start])
    paths = {start: [start]}

    while stack:
        p = stack.pop()
        if p == goal:
            return paths[p]
        for n in neighbors(p):
            if valid(n) and n not in seen:
                seen.add(n)
                stack.append(n)
                paths[n] = paths[p] + [n]

    return []

